using System.Reflection;
using CaseIntake.Contracts.Cases;
using CaseIntake.Domain.Cases;

namespace CaseIntake.Cases.Tests;

/// <summary>
/// Spec 4.4: the case ID is generated by the system and immutable. The database side (positive identity-always
/// <c>bigint</c>, supplied IDs refused, changing a saved ID throws) is covered by <c>CaseSchemaTests</c>; these tests
/// prove no client-supplied value can carry or change an ID.
/// </summary>
public class CaseIdContractTests
{
    private static readonly string[] IdPropertyNames = ["Id", "CaseId"];

    private static Type[] RequestTypes { get; } = [.. typeof(CreateCaseRequest).Assembly.GetExportedTypes()
        .Where(t => t.Namespace == typeof(CreateCaseRequest).Namespace && t.Name.EndsWith("Request", StringComparison.Ordinal))];

    public static TheoryData<Type> CaseRequestTypes() => [.. RequestTypes];

    [Fact]
    public void Every_case_mutation_request_is_covered()
    {
        Assert.Equal(
            [nameof(AssignCaseRequest), nameof(ChangeStatusRequest), nameof(CreateCaseRequest), nameof(UpdateCaseRequest)],
            RequestTypes.Select(t => t.Name).Order(StringComparer.Ordinal));
    }

    [Theory]
    [MemberData(nameof(CaseRequestTypes))]
    public void Requests_carry_no_case_ID(Type requestType)
    {
        var idProperties = requestType.GetProperties(BindingFlags.Public | BindingFlags.Instance)
            .Where(p => IdPropertyNames.Contains(p.Name, StringComparer.OrdinalIgnoreCase))
            .Select(p => p.Name);

        Assert.Empty(idProperties);
    }

    [Fact]
    public void Updates_and_status_changes_take_the_ID_only_from_the_route()
    {
        foreach (var name in new[] { nameof(ICaseService.UpdateAsync), nameof(ICaseService.ChangeStatusAsync) })
        {
            var parameters = typeof(ICaseService).GetMethod(name)!.GetParameters();
            Assert.Equal(("id", typeof(long)), (parameters[0].Name, parameters[0].ParameterType));
        }
        var assign = typeof(ICaseAssignmentService).GetMethod(nameof(ICaseAssignmentService.AssignAsync))!.GetParameters();
        Assert.Equal(("id", typeof(long)), (assign[0].Name, assign[0].ParameterType));
    }

    [Fact]
    public void The_entity_ID_has_no_public_setter_and_starts_unassigned()
    {
        var id = typeof(Case).GetProperty(nameof(Case.Id))!;
        Assert.Equal(typeof(long), id.PropertyType);
        Assert.False(id.SetMethod?.IsPublic ?? false);
        Assert.False(id.SetMethod?.IsFamily ?? false);

        var entity = Case.Create("Valid title", null, null, "worker", DateTimeOffset.UnixEpoch);

        Assert.Equal(0, entity.Id);   // only the database assigns it
    }
}
